{
  "session_name": "sample workspace",
  "start_directory": "~",
  "windows": [
    {
      "window_name": "focused window",
      "layout": "main-horizontal",
      "focus": true,
      "panes": [
        {
          "shell_command": [
            "cd ~"
          ]
        },
        {
          "shell_command": [
            "cd /usr"
          ],
          "focus": true
        },
        {
          "shell_command": [
            "cd ~",
            "echo \"moo\"",
            "top"
          ]
        }
      ]
    },
    {
      "window_name": "window 2",
      "panes": [
        {
          "shell_command": [
            "top"
          ],
          "focus": true
        },
        {
          "shell_command": [
            "echo \"hey\""
          ]
        },
        {
          "shell_command": [
            "echo \"moo\""
          ]
        }
      ]
    },
    {
      "window_name": "window 3",
      "panes": [
        {
          "shell_command": "cd /",
          "focus": true
        },
        "pane",
        "pane"
      ]
    }
  ]
}

{
  "session_name": "shorthands",
  "windows": [
    {
      "window_name": "long form",
      "panes": [
        {
          "shell_command": [
            "echo 'did you know'",
            "echo 'you can inline'"
          ]
        },
        {
          "shell_command": "echo 'single commands'"
        },
        "echo 'for panes'"
      ]
    }
  ]
}

{
  "session_name": "Environment variables test",
  "environment": {
    "EDITOR": "/usr/bin/vim",
    "DJANGO_SETTINGS_MODULE": "my_app.settings.local",
    "SERVER_PORT": "8009"
  },
  "windows": [
    {
      "window_name": "Django project",
      "panes": [
        "./manage.py runserver 0.0.0.0:${SERVER_PORT}"
      ]
    },
    {
      "window_name": "Another Django project",
      "environment": {
        "DJANGO_SETTINGS_MODULE": "my_app.settings.local",
        "SERVER_PORT": "8010"
      },
      "panes": [
        "./manage.py runserver 0.0.0.0:${SERVER_PORT}",
        {
          "environment": {
            "DJANGO_SETTINGS_MODULE": "my_app.settings.local-testing",
            "SERVER_PORT": "8011"
          },
          "shell_command": "./manage.py runserver 0.0.0.0:${SERVER_PORT}"
        }
      ]
    }
  ]
}

{
  "session_name": "start directory",
  "start_directory": "/var/",
  "windows": [
    {
      "window_name": "should be /var/",
      "panes": [
        {
          "shell_command": [
            "echo \"\\033c",
            "it trickles down from session-level\""
          ]
        },
        "echo hello"
      ]
    },
    {
      "window_name": "should be /var/log",
      "start_directory": "log",
      "panes": [
        {
          "shell_command": [
            "echo '\\033c",
            "window start_directory concatenates to session start_directory",
            "if it is not absolute'"
          ]
        },
        "echo hello"
      ]
    },
    {
      "window_name": "should be ~",
      "start_directory": "~",
      "panes": [
        {
          "shell_command": [
            "echo \\\\033c ~ has precedence. note: remember to quote ~ in YAML"
          ]
        },
        "echo hello"
      ]
    },
    {
      "window_name": "should be /bin",
      "start_directory": "/bin",
      "panes": [
        "echo '\\033c absolute paths also have precedence.'",
        "echo hello"
      ]
    },
    {
      "window_name": "should be workspace file's dir",
      "start_directory": "./",
      "panes": [
        {
          "shell_command": [
            "echo '\\033c",
            "./ is relative to workspace file location",
            "../ will be parent of workspace file",
            "./test will be \\\"test\\\" dir inside dir of workspace file'"
          ]
        },
        {
          "shell_command": [
            "echo '\\033c",
            "This way you can load up workspaces from projects and maintain",
            "relative paths.'"
          ]
        }
      ]
    }
  ]
}

{
  "session_name": "libtmux",
  "start_directory": "/tmp",
  "shell_command_before": [
    "echo setup"
  ],
  "windows": [
    {
      "window_name": "work",
      "focus": true,
      "layout": "main-horizontal",
      "options": {
        "main-pane-height": "60%"
      },
      "panes": [
        {
          "focus": true
        },
        "echo second"
      ]
    },
    {
      "window_name": "docs",
      "shell_command_before": "echo docs-setup",
      "panes": [
        "echo only"
      ]
    }
  ]
}

{
  "session_name": "corpus",
  "start_directory": "${PROJECT_ROOT}",
  "options": {
    "default-command": "exec /bin/sh",
    "@corpus-session": "yaml-original"
  },
  "environment": {
    "CORPUS_SESSION": "yaml-root",
    "CORPUS_LAYER": "session"
  },
  "shell_command_before": [
    {
      "cmd": "echo session >> order.txt"
    }
  ],
  "windows": [
    {
      "window_name": "yaml-editor",
      "start_directory": "window",
      "layout": "even-horizontal",
      "focus": true,
      "options": {
        "@corpus-window": "${OPTION_TAG}"
      },
      "environment": {
        "CORPUS_WINDOW": "yaml-window",
        "CORPUS_LAYER": "window"
      },
      "shell_command_before": [
        {
          "cmd": "echo window >> order.txt"
        }
      ],
      "panes": [
        {
          "shell_command": [
            {
              "cmd": "echo command >> order.txt"
            },
            "echo \"$CORPUS_SESSION|$CORPUS_WINDOW|$CORPUS_PANE|$CORPUS_LAYER\" > environment.txt",
            "tmux wait-for -S corpus-yaml-first"
          ]
        },
        {
          "start_directory": "pane",
          "focus": true,
          "options": {
            "@corpus-pane": "yaml"
          },
          "environment": {
            "CORPUS_PANE": "yaml-pane",
            "CORPUS_LAYER": "pane"
          },
          "shell_command_before": [
            {
              "cmd": "echo pane >> order.txt"
            }
          ],
          "shell_command": [
            "echo command >> order.txt",
            "echo \"$CORPUS_SESSION|$CORPUS_WINDOW|$CORPUS_PANE|$CORPUS_LAYER\" > environment.txt",
            "tmux wait-for -S corpus-yaml-second"
          ]
        }
      ]
    }
  ]
}
